import{_ as e,o as t,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第七次全体会议公报","description":"","frontmatter":{"prev":{"text":"十二届七中全会简介","link":"./"},"next":{"text":"十三大简介","link":"/13/"}},"headers":[],"relativePath":"12/7/中国共产党第十二届中央委员会第七次全体会议公报.md","filePath":"12/7/中国共产党第十二届中央委员会第七次全体会议公报.md"}'),r={name:"12/7/中国共产党第十二届中央委员会第七次全体会议公报.md"};function n(o,_,s,i,c,l){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="中国共产党第十二届中央委员会第七次全体会议公报" tabindex="-1">中国共产党第十二届中央委员会第七次全体会议公报 <a class="header-anchor" href="#中国共产党第十二届中央委员会第七次全体会议公报" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第七次全体会议公报&quot;">​</a></h1><p><em>（中国共产党第十二届中央委员会第七次全体会议一九八七年十月二十日通过）</em></p><p>  中国共产党第十二届中央委员会第七次全体会议，1987年10月20日在北京举行。</p><p>  出席这次会议的，有中央委员202人，候补中央委员122人。列席会议的，有中央顾问委员会委员161人，中央纪律检查委员会委员121人，有关负责同志39人。中央政治局常委赵紫阳同志、邓小平同志、李先念同志、陈云同志、胡耀邦同志，主持了这次会议。</p><p>  全会决定，1987年10月25日在北京召开中国共产党第十三次全国代表大会。</p><p>  全会讨论并通过了中央委员会向党的第十三次全国代表大会的报告，讨论并通过了《中国共产党章程部分条文修正案》，一致决定将这两个文件提请党的第十三次全国代表大会审议。</p><p>  全会讨论并原则同意《政治体制改革总体设想》，决定将这个文件的主要内容写入中央委员会向党的第十三次全国代表大会的报告。</p><p>  全会确认1987年1月16日中共中央政治局扩大会议关于接受胡耀邦同志辞去中央委员会总书记职务的请求的决定和推选赵紫阳同志代理中央委员会总书记的决定。</p><p>  全会还确认1987年7月14日中共中央政治局关于撤销沈图同志中央委员职务的决定。</p><p>  全体会议之前，举行了5天预备会议。与会同志在民主、团结和生动活泼的气氛中，就上述议题进行了认真讨论。</p>',10)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
